return [
  // ── Médias financiers spécialisés Maroc ──
  { json: { url: 'https://www.financesnews.ma/feed',            name: 'Finances News',       cat: 'Finance Maroc',    morocco: true }},
  { json: { url: 'https://www.boursenews.ma/feed',              name: 'Bourse News',         cat: 'Finance Maroc',    morocco: true }},
  { json: { url: 'https://www.leconomiste.com/feed',            name: "L'Economiste",        cat: 'Économie Maroc',   morocco: true }},
  { json: { url: 'https://www.leseco.ma/feed',                  name: 'Les Eco',             cat: 'Économie Maroc',   morocco: true }},
  { json: { url: 'https://www.challenge.ma/feed',               name: 'Challenge Maroc',     cat: 'Business Maroc',   morocco: true }},
  { json: { url: 'https://medias24.com/feed',                   name: 'Medias24',            cat: 'Actualités Maroc', morocco: true }},
  { json: { url: 'https://lnt.ma/feed/',                        name: 'La Nouvelle Tribune', cat: 'Économie Maroc',   morocco: true }},
  { json: { url: 'https://www.lematin.ma/rss/Une.rss',          name: 'Le Matin',            cat: 'Actualités Maroc', morocco: true }},
  { json: { url: 'https://www.agenceecofin.com/rss/toutes-les-nouvelles', name: 'Agence Ecofin', cat: 'Finance Afrique', morocco: false }},
  // ── Fintechs & acteurs paiement Maroc ──
  { json: { url: 'https://www.hps-worldwide.com/feed/',         name: 'HPS Worldwide',       cat: 'Fintech Maroc',    morocco: true }},
  // ── Régulateurs & institutionnels Maroc ──
  { json: { url: 'https://www.bkam.ma/rss/Communiques',         name: 'Bank Al-Maghrib',     cat: 'Régulation Maroc', morocco: true }},
  { json: { url: 'https://www.finances.gov.ma/rss/actualites',  name: 'Min. Finances Maroc', cat: 'Régulation Maroc', morocco: true }},
  // ── Visa & Mastercard MEA ──
  { json: { url: 'https://ma.visamiddleeast.com/fr_MA/about-visa/newsroom/rss.xml', name: 'Visa Maroc', cat: 'Paiement Global', morocco: false }},
  { json: { url: 'https://www.mastercard.com/mea/fr/news-and-trends/press/rss.xml', name: 'Mastercard MEA', cat: 'Paiement Global', morocco: false }},
  // ── Paiement international ──
  { json: { url: 'https://thepaypers.com/rss/all',              name: 'The Paypers',         cat: 'Paiement Global',  morocco: false }},
  { json: { url: 'https://www.finextra.com/rss/headlines.aspx', name: 'Finextra',            cat: 'Fintech Global',   morocco: false }}
];

// ================================================================
// NIVEAU 1 — PRÉ-SCORING PAR MOTS-CLÉS
// ================================================================

const SOURCE_MAP = {
  'financesnews.ma':        { name:'Finances News',       cat:'Finance Maroc',    morocco:true  },
  'boursenews.ma':          { name:'Bourse News',         cat:'Finance Maroc',    morocco:true  },
  'leconomiste.com':        { name:"L'Economiste",        cat:'Économie Maroc',   morocco:true  },
  'leseco.ma':              { name:'Les Eco',             cat:'Économie Maroc',   morocco:true  },
  'challenge.ma':           { name:'Challenge Maroc',     cat:'Business Maroc',   morocco:true  },
  'medias24.com':           { name:'Medias24',            cat:'Actualités Maroc', morocco:true  },
  'lnt.ma':                 { name:'La Nouvelle Tribune', cat:'Économie Maroc',   morocco:true  },
  'lematin.ma':             { name:'Le Matin',            cat:'Actualités Maroc', morocco:true  },
  'agenceecofin.com':       { name:'Agence Ecofin',       cat:'Finance Afrique',  morocco:false },
  'hps-worldwide.com':      { name:'HPS Worldwide',       cat:'Fintech Maroc',    morocco:true  },
  'bkam.ma':                { name:'Bank Al-Maghrib',     cat:'Régulation Maroc', morocco:true  },
  'finances.gov.ma':        { name:'Min. Finances Maroc', cat:'Régulation Maroc', morocco:true  },
  'visamiddleeast.com':     { name:'Visa Maroc',          cat:'Paiement Global',  morocco:false },
  'mastercard.com':         { name:'Mastercard MEA',      cat:'Paiement Global',  morocco:false },
  'thepaypers.com':         { name:'The Paypers',         cat:'Paiement Global',  morocco:false },
  'finextra.com':           { name:'Finextra',            cat:'Fintech Global',   morocco:false }
};

// Mots-clés positifs (+3 chacun)
const KEYWORDS_CORE = [
  'paiement','payment','monétique','monetique','wallet','m-wallet','portefeuille électronique',
  'qr code','softpos','soft pos','tap to phone','tap to mobile','tpe','terminal de paiement',
  'carte bancaire','cartes bancaires','sans contact','contactless','tokenisation',
  'mobile money','virement','e-commerce payment','passerelle de paiement','payment gateway',
  'interopérabilité','interoperabilite','switch','acquiring','merchant acquiring',
  'encaissement digital','recouvrement digital','paiement marchand','paiement commerçant',
  'fraude paiement','sécurité paiement','open banking','bnpl','embedded finance','fatourati'
];

// Acteurs à surveiller (+2 chacun)
const KEYWORDS_ACTORS = [
  'bank al-maghrib','bkam','ammc','acaps','cmi','centre monétique interbancaire',
  'hps','switch al maghrib','morocco fintech','visa','mastercard',
  'cash plus','wafacash','barid cash','al barid bank','inwi money','orange money',
  'bank of africa','bmce','bmci','banque populaire','sgmb','société générale maroc',
  'cih bank','credit du maroc','cfg bank','umnia bank','dabapay','payzone','m2t'
];

// Contexte Maroc (+2 chacun)
const KEYWORDS_MAROC = [
  'maroc','marocain','marocaine','casablanca','rabat','marrakech','kenitra',
  'royaume du maroc','bank al-maghrib','digitalisation au maroc','fintech maroc'
];

// Signaux business (+2 chacun)
const KEYWORDS_SIGNALS = [
  'lancement','lance','déploiement','déploie','partenariat','accord','s\'allie',
  'investit','acquisition','prise de participation','homologation','agrément','licence',
  'sandbox','circulaire','réglementation','cadre réglementaire','appel d\'offres',
  'nouvelle offre','nouveau service','nouvelle solution','intégration','migration'
];

// Mots-clés négatifs (-3 chacun)
const KEYWORDS_NEGATIVE = [
  'tombola','jeu concours','promotion grand public','bon plan','sponsoring',
  'recrutement','rh ','top employer','rse ','fondation ','durabilité',
  'assemblée générale','nomination','carrière','formation interne',
  'météo','agriculture','céréale','engrais','football','sport','culture',
  'politique étrangère','diplomatie','ambassadeur','militaire','sécurité nationale',
  'immobilier','foncier','urbanisme','transport funéraire','santé publique'
];

const getDomain = (url) => {
  try { return url.replace(/^https?:\/\//, '').replace(/^www\./, '').split('/')[0]; }
  catch(e) { return ''; }
};

const calcScore = (text) => {
  const t = text.toLowerCase();
  let score = 0;
  KEYWORDS_CORE.forEach(kw => { if (t.includes(kw)) score += 3; });
  KEYWORDS_ACTORS.forEach(kw => { if (t.includes(kw)) score += 2; });
  KEYWORDS_MAROC.forEach(kw => { if (t.includes(kw)) score += 2; });
  KEYWORDS_SIGNALS.forEach(kw => { if (t.includes(kw)) score += 2; });
  KEYWORDS_NEGATIVE.forEach(kw => { if (t.includes(kw)) score -= 3; });
  return score;
};

const articles = [];
for (const item of $input.all()) {
  try {
    const j = item.json;
    if (!j || !j.title || typeof j.title !== 'string') continue;
    const title = j.title.trim();
    if (!title) continue;
    const link = String(j.link || j.guid || '').trim();
    const domain = getDomain(link);
    const src = SOURCE_MAP[domain] || { name: domain || 'Inconnu', cat: 'Autre' };
    const desc = String(j['content:encodedSnippet'] || j.contentSnippet || j.content || j.summary || '')
      .replace(/<[^>]+>/g, '').replace(/&nbsp;/g,' ').replace(/&amp;/g,'&').trim().slice(0, 400);
    const pubDate = String(j.isoDate || j.pubDate || '');
    const textToScore = title + ' ' + desc;
    let preScore = calcScore(textToScore);
    // Bonus +5 pour les sources marocaines — elles parlent du contexte local
    if (src.morocco) preScore += 5;

    // Seuil très bas : éliminer uniquement le contenu clairement hors-sujet
    if (preScore < -3) continue;

    articles.push({ title, link, pubDate, sourceName: src.name, sourceCategory: src.cat, desc, preScore });
  } catch(e) { continue; }
}

// Trier par score décroissant, prendre les 15 meilleurs
const limited = articles.sort((a,b) => b.preScore - a.preScore).slice(0, 15);
console.log('Articles valides après pré-scoring : ' + articles.length + ' — envoi à Groq : ' + limited.length);
if (limited.length === 0) return [{ json: { _empty: true } }];

const lines = limited.map((a, i) =>
  (i+1) + '. TITRE: ' + a.title + ' | SOURCE: ' + a.sourceName + ' | PRE_SCORE: ' + a.preScore + ' | DESC: ' + a.desc
).join('\n\n');

const payload = {
  model: 'llama-3.1-8b-instant',
  temperature: 0.1,
  max_tokens: 4000,
  messages: [
    {
      role: 'system',
      content: 'Tu es un analyste senior en veille stratégique bancaire au Maroc. Ta mission est d\'évaluer si chaque article est réellement pertinent pour Attijariwafa Bank dans le paiement multicanal.\n\nTu dois privilégier : paiement mobile, wallet, QR code, cartes bancaires, TPE/SoftPOS, e-commerce payment, fintech marocaine, banques concurrentes marocaines (CIH Bank, Banque Populaire, BMCE Bank of Africa, Société Générale Maroc, BMCI, Crédit du Maroc, CFG Bank, Al Barid Bank), régulation paiements/fintech au Maroc, CMI, Bank Al-Maghrib, Visa, Mastercard, HPS.\n\nTu dois pénaliser : corporate générique, RH, RSE, sponsoring, météo, agriculture, politique sans lien paiement, contenu sans lien avec le Maroc.\n\nRetourne UNIQUEMENT un JSON valide sans markdown ni backticks : { "articles": [ ... ] }\n\nPour chaque article ces champs OBLIGATOIRES :\n- is_relevant: true/false\n- relevance_score: 0 à 100 (0-29=rejet, 30-59=à revoir, 60-100=à conserver)\n- priority: high/medium/low\n- categorie: Paiement multicanal | Banque concurrente | Fintech | Régulation | Gouvernement/Secteur public | Innovation | Partenariat | Nouveau produit/service | Autre\n- type_signal: Lancement produit | Partenariat | Nouvel acteur | Évolution réglementaire | Initiative concurrente | Digitalisation | Levée de fonds | Tendance émergente | Information générale\n- main_actor: acteur principal\n- competitor_bank: banque concurrente citée ou vide\n- summary: résumé 2 phrases orienté business en français\n- why_it_matters: pourquoi c\'est important pour Attijariwafa Bank\n- opportunity: opportunité concrète ou vide\n- threat: menace concrète ou vide\n- recommended_action: action recommandée ou vide\n- reason_if_rejected: raison du rejet si is_relevant=false, sinon vide'
    },
    {
      role: 'user',
      content: 'Analyse ces ' + limited.length + ' articles. IMPORTANT : certains viennent de sources marocaines (Medias24, L\'Economiste, Finances News, etc.) — accorde-leur plus de crédit même si le titre paraît générique, car le contexte Maroc est implicite.\n\n' + lines
    }
  ]
};

const meta = limited.map(a => ({ title: a.title, link: a.link, pubDate: a.pubDate, sourceName: a.sourceName, preScore: a.preScore }));
return [{ json: { payload, meta } }];

// ================================================================
// NIVEAU 3 — DÉCISION FINALE : keep / review / reject
// ================================================================
const raw = $input.first().json.choices?.[0]?.message?.content || '{}';
let parsed = {};
try {
  // Nettoyer si Groq ajoute des backticks
  const cleaned = raw.replace(/^```json?\s*/,'').replace(/\s*```$/,'').trim();
  parsed = JSON.parse(cleaned);
} catch(e) { parsed = { articles: [] }; }

const aiArticles = Array.isArray(parsed.articles) ? parsed.articles : [];
const meta = $('Pré-scoring & Préparer').first().json.meta || [];

const now = new Date();
const dateCollecte = now.toLocaleDateString('fr-FR', { day:'2-digit', month:'2-digit', year:'numeric' }) + ' ' + now.toLocaleTimeString('fr-FR', { hour:'2-digit', minute:'2-digit' });

return aiArticles.map((ai, i) => {
  const m = meta[i] || {};
  const pubDateFormatted = m.pubDate ? new Date(m.pubDate).toLocaleDateString('fr-FR', { day:'2-digit', month:'2-digit', year:'numeric' }) : '';

  // Décision finale
  const score = Number(ai.relevance_score) || 0;
  let decision = 'Rejeté';
  if (score >= 60) decision = 'À conserver';
  else if (score >= 30) decision = 'À revoir';

  return { json: {
    'Date de collecte':   dateCollecte,
    'Titre':              m.title || '',
    'Source':             m.sourceName || '',
    'Lien':               m.link || '',
    'Date publication':   pubDateFormatted,
    'Résumé':             ai.summary || '',
    'Catégorie':          ai.categorie || 'Autre',
    'Sous-catégorie':     ai.why_it_matters || '',
    'Type de signal':     ai.type_signal || '',
    'Acteurs cités':      ai.main_actor || '',
    'Banque concurrente': ai.competitor_bank || '',
    'Importance':         ai.priority === 'high' ? 'Élevée' : ai.priority === 'medium' ? 'Moyenne' : 'Faible',
    'Opportunité':        ai.opportunity || '',
    'Menace':             ai.threat || '',
    'Impact pour AWB':    ai.why_it_matters || '',
    'Action recommandée': ai.recommended_action || '',
    'Pertinent':          ai.is_relevant === true ? 'true' : 'false',
    'Statut':             decision
  }};
});
